SourceCode.Declaration:
public class AVACreateCycleCountService
{
    AVACycleCountGroupByType    cycleCountGroupByType;
    WHSParameters               parameters;

}

Method.Source:
public void create(AVACreateCycleCountContract _contract)
{
    Query       query;
    QueryRun    queryRun;
    InventSum   inventSum;
    InventDim   inventDim;

    this.init();
    this.initFromContract(_contract);

    query       = _contract.getQuery();
    queryRun    = new QueryRun(query);

    while (queryRun.next())
    {
        inventSum = queryRun.get(tableNum(InventSum));
        inventDim = queryRun.get(tableNum(InventDim));

        if (this.validateCreate(inventSum, inventDim))
        {
            this.doCreate(inventSum, inventDim);
        }
    }
}

protected boolean validateCreate(InventSum _inventSum, InventDim  _inventDim)
{
    boolean     valid;
    WMSLocation wmsLocation;
    WHSLocType  locationType;

    wmsLocation     = WMSLocation::find(_inventDim.wmsLocationId, _inventDim.InventLocationId);
    locationType    = wmsLocation.whsLocationType();

    if (wmsLocation.RecId           > 0 
     && locationType                != parameters.ShipFinalLocType
     && locationType                != parameters.UserLocType
     && locationType                != parameters.StageLocType
     && _inventSum.PhysicalInvent    > 0)
    {
        valid = true;
    }
    else    
    {
        valid = checkFailed("@NDX:NotValidCountingTypeLocation");
    }

    // If this location is not Cycle Countable, skip it.
    if (!WHSLocationProfile::find(wmsLocation.LocProfileId).CycleCountable)
    {
        valid = checkFailed("@NDX:NotValidCountingLocation");
    }

    if (WHSWorkLine::avaAnyCycleCountWorkExistsAtLocation(wmsLocation))
    {
        valid = checkFailed("@NDX:WorkAlreadyExists");
    }

    return valid;
}

protected void doCreate(InventSum _inventSum, InventDim  _inventDim)
{
    WhsCycleCountCreatePlan cycleCountCreatePlan;
    Set		                itemsAndDimensionsForWorkCreationSet;
    WMSLocation             wmsLocation;

    wmsLocation                             = WMSLocation::find(_inventDim.wMSLocationId, _inventDim.InventLocationId);
    cycleCountCreatePlan                    = WhsCycleCountCreatePlan::construct();
    itemsAndDimensionsForWorkCreationSet    = new Set(Types::Container);

    this.manageItemAndDims(_inventSum, _inventDim, itemsAndDimensionsForWorkCreationSet);

    if (cycleCountGroupByType == AVACycleCountGroupByType::Location)
    {
        cycleCountCreatePlan.avaParmisWorkTemplateBreakingWorkLines(false);
    }
    else 
    {
        cycleCountCreatePlan.avaParmisWorkTemplateBreakingWorkLines(true);
    }

    cycleCountCreatePlan.avaCreateWork(wmsLocation, itemsAndDimensionsForWorkCreationSet);
}

private void manageItemAndDims(InventSum _inventSum, InventDim  _inventDim, Set _itemsAndDimensionsForWorkCreationSet)
{
    ItemId      itemIdForWorkCreation;
    InventDimId inventDimIdForWorkCreation;

    if (cycleCountGroupByType != AVACycleCountGroupByType::Location)
    {
        [itemIdForWorkCreation, inventDimIdForWorkCreation] = this.findItemAndDimensionForWorkCreation(_inventSum, _inventDim);

        if (itemIdForWorkCreation != '')
        {
            _itemsAndDimensionsForWorkCreationSet.add([itemIdForWorkCreation, inventDimIdForWorkCreation]);
        }
    }
}

private container findItemAndDimensionForWorkCreation(InventSum _inventSum, InventDim _productDim)
{
    if (_productDim.anyProductDimensionSpecified())
    {
        if (!_productDim.RecId)
        {
            _productDim = this.findProductDimensionsInventDim(_inventSum.InventDimId);
        }

        return [_inventSum.ItemId, _productDim.InventDimId];

    }
    else
    {
        return [_inventSum.ItemId, ''];
    }
}

private InventDim findProductDimensionsInventDim(InventDimId _inventDimId)
{
    InventDim inventDim = InventDim::find(_inventDimId);

    return InventDim::findDim(InventProductDimension::createInventDimFromTable(inventDim));
}
